DO $$
DECLARE
  rec RECORD;
  prior_discharge DATE;
  days_diff INTEGER;
BEGIN
  FOR rec IN 
    SELECT admission_id, patient_id, patient_age, admission_date, severity_score, high_risk
    FROM patient_admissions
    ORDER BY admission_date, admission_id
  LOOP
    SELECT MAX(discharge_date) INTO prior_discharge
    FROM patient_admissions
    WHERE patient_id = rec.patient_id
      AND discharge_date IS NOT NULL
      AND discharge_date < rec.admission_date;

    IF prior_discharge IS NOT NULL THEN
      days_diff := rec.admission_date - prior_discharge;
      IF days_diff <= 30 THEN
        UPDATE patient_admissions
        SET severity_score = severity_score + 10
        WHERE admission_id = rec.admission_id;
      END IF;
    END IF;

    UPDATE patient_admissions
    SET high_risk = TRUE
    WHERE admission_id = rec.admission_id
      AND severity_score > 75;

    UPDATE patient_admissions
    SET severity_score = severity_score + 5
    WHERE admission_id = rec.admission_id
      AND high_risk = TRUE
      AND patient_age > 65;
  END LOOP;
END $$;

SELECT * FROM patient_admissions ORDER BY admission_id;

