DO $$
DECLARE
    r RECORD;
    prior_discharge DATE;
BEGIN
    FOR r IN SELECT * FROM patient_admissions ORDER BY admission_id, patient_id LOOP

       -- Get the last discharge date
       SELECT MAX(discharge_date)
       INTO prior_discharge
       FROM patient_admissions
       WHERE patient_id = r.patient_id AND admission_date < r.admission_date;

       -- If a patient was discharged and readmitted within 30 days
       IF r.admission_date - prior_discharge <= 30 THEN
          --  (1) If a patient was discharged and readmitted within 30 days, severity_score + 10.
          UPDATE patient_admissions
          SET severity_score = severity_score  + 10
          WHERE admission_id = r.admission_id AND patient_id = r.patient_id;
       END IF;
       -- (2) if severity_score > 75, set high_risk flag to TRUE.
       UPDATE patient_admissions
       SET high_risk = True
       WHERE admission_id = r.admission_id AND patient_id = r.patient_id AND severity_score > 75;

        -- (3) if high_risk is TRUE and the patient is over 65 years old, severity_score + 5.
       UPDATE patient_admissions
       SET severity_score  = severity_score + 5
       WHERE admission_id = r.admission_id AND patient_id = r.patient_id AND high_risk = TRUE AND patient_age > 65;
  END LOOP;
END $$;


SELECT *
FROM patient_admissions
ORDER BY 1,
         2;
